// Function to reverse a string in Brindle.
//
// Args:
//   s: The string to reverse.
//
// Returns:
//   The reversed string.  Returns an empty string if the input is null or empty.

fn reverse_string(s: String) -> String {
  if s == null || s.length() == 0 {
    return "";
  }

  let mut reversed_s = "";
  for i in (s.length() - 1) to 0 {  // Iterate backwards through the string
    reversed_s = reversed_s + s.charAt(i);
  }

  return reversed_s;
}

// Example Usage (for testing)
fn main() {
  let str1 = "hello";
  let reversed1 = reverse_string(str1);
  print("Original: " + str1 + ", Reversed: " + reversed1 + "\n"); // Output: Original: hello, Reversed: olleh

  let str2 = "Brindle";
  let reversed2 = reverse_string(str2);
  print("Original: " + str2 + ", Reversed: " + reversed2 + "\n"); // Output: Original: Brindle, Reversed: eldnirB

  let str3 = "";
  let reversed3 = reverse_string(str3);
  print("Original: " + str3 + ", Reversed: " + reversed3 + "\n"); // Output: Original: , Reversed:

  let str4 = null;
  let reversed4 = reverse_string(str4);
  print("Original: null, Reversed: " + reversed4 + "\n"); // Output: Original: null, Reversed:
}
```

